test("renewals use Studio caps and the original tenant, with replay and cancellation", () => {
  const dispatch = planner(catalog());
  dispatch(book("first"));
  const operation = renew("first", "next", {tenant: "small"});
  assert.deepEqual(dispatch(operation), {status: "booked", id: "next", remaining: 1});
  assert.equal(dispatch(operation).status, "replay");
  assert.equal(dispatch({...operation, units: 6}).status, "conflict");
  assert.equal(dispatch(renew("first", "over", {units: 2})).status, "full");
  assert.equal(dispatch(renew("first", "last", {units: 1})).remaining, 0);
  dispatch({action: "cancel", service: "studio", id: "next"});
  assert.equal(dispatch(operation).status, "cancelled");
  assert.equal(dispatch(renew("first", "replacement")).status, "booked");
